code='''def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    # The aligned pair defines a trunk; remaining markers branch perpendicularly to it.
    by_row = {}
    by_col = {}
    for r, c in pts:
        by_row.setdefault(r, []).append(c)
        by_col.setdefault(c, []).append(r)
    if any(len(cs) >= 2 for cs in by_row.values()):
        r0 = max((r for r, cs in by_row.items() if len(cs) >= 2), key=lambda r: len(by_row[r]))
        lo, hi = min(by_row[r0]), max(by_row[r0])
        for c in range(lo, hi + 1):
            if out[r0][c] == 0: out[r0][c] = 3
        for r, c in pts:
            if r != r0:
                for rr in range(min(r, r0), max(r, r0) + 1):
                    if out[rr][c] == 0: out[rr][c] = 3
    else:
        c0 = max((c for c, rs in by_col.items() if len(rs) >= 2), key=lambda c: len(by_col[c]))
        lo, hi = min(by_col[c0]), max(by_col[c0])
        for r in range(lo, hi + 1):
            if out[r][c0] == 0: out[r][c0] = 3
        for r, c in pts:
            if c != c0:
                for cc in range(min(c, c0), max(c, c0) + 1):
                    if out[r][cc] == 0: out[r][cc] = 3
    return out
'''
